class Solution {
public:
    long long maximumTotalCost(vector<int>& nums) {
        long long f = nums[0], g = LLONG_MIN;
        for (size_t i = 1; i < nums.size(); i++) {
            long long nf = max(f, g) + nums[i];
            long long ng = f - nums[i];
            f = nf; g = ng;
        }
        return max(f, g);
    }
};

