from functools import lru_cache
class Solution:
    def maximumTotalCost(self, nums: List[int]) -> int:
        n = len(nums)
        @lru_cache(maxsize=None)
        def dfs(i, pos):
            if i == n:
                return 0
            if pos:
                return max(nums[i] + dfs(i + 1, False),   # alternate
                           nums[i] + dfs(i + 1, True))    # cut, restart with +
            return nums[i] + dfs(i + 1, True)             # must restart with +
        return dfs(0, True)

