class Solution {
    vector<array<long long,2>> memo;
    vector<int>* a;
    long long dfs(int i, bool pos) {
        int n = a->size();
        if (i == n) return 0;
        if (memo[i][pos] != LLONG_MIN) return memo[i][pos];
        long long res = (*a)[i] + dfs(i + 1, true);
        if (pos) res = max(res, (long long)(*a)[i] + dfs(i + 1, false));
        return memo[i][pos] = res;
    }
public:
    long long maximumTotalCost(vector<int>& nums) {
        a = &nums;
        memo.assign(nums.size(), {LLONG_MIN, LLONG_MIN});
        return dfs(0, true);
    }
};

