class Solution {
    private Long[][] memo;
    private int[] nums;
    private long dfs(int i, boolean pos) {
        if (i == nums.length) return 0;
        if (memo[i][pos ? 1 : 0] != null) return memo[i][pos ? 1 : 0];
        long res = nums[i] + dfs(i + 1, true);
        if (pos) res = Math.max(res, (long) nums[i] + dfs(i + 1, false));
        return memo[i][pos ? 1 : 0] = res;
    }
    public long maximumTotalCost(int[] nums) {
        this.nums = nums;
        memo = new Long[nums.length][2];
        return dfs(0, true);
    }
}

