    const memo = Array.from({length: n}, () => [null, null]);
    const dfs = (i, pos) => {
        if (i === n) return 0;
        if (memo[i][pos ? 1 : 0] !== null) return memo[i][pos ? 1 : 0];
        let res = nums[i] + dfs(i + 1, true);
        if (pos) res = Math.max(res, nums[i] + dfs(i + 1, false));
        return memo[i][pos ? 1 : 0] = res;
    };
    return dfs(0, true);
